{
  "ruleset": {
    "id": "default-llm",
    "version": 2
  },
  "requested_model": "auto",
  "messages": [
    {
      "role": "user",
      "content": "Make me a scientific calculator!"
    },
    {
      "role": "assistant",
      "content": "Here it is: a calculator with sin, cos and a history pane."
    },
    {
      "role": "user",
      "content": "Looks great. Now what is the weather like on Mars?"
    }
  ]
}

{
  "ruleset": {
    "id": "default-signals",
    "version": 1
  },
  "requested_model": "auto",
  "messages": [
    {
      "role": "system",
      "content": "You are a helpful assistant."
    },
    {
      "role": "user",
      "content": "Which homeowner is on project 4412, and can you draft them a permit update?"
    },
    {
      "role": "assistant",
      "content": null,
      "tool_calls": [
        {
          "id": "call_1",
          "type": "function",
          "function": {
            "name": "phoenix_run_query",
            "arguments": "{\"sql\": \"SELECT homeowner, email, address FROM projects WHERE id = 4412\"}"
          }
        }
      ]
    },
    {
      "role": "tool",
      "tool_call_id": "call_1",
      "content": "[{\"homeowner\": \"Jordan Example\", \"email\": \"jordan.example@example.com\", \"address\": \"1482 W Cedar Hollow Dr, Lehi, UT 84043\"}]"
    },
    {
      "role": "user",
      "content": "Great, now make the email sound friendlier."
    }
  ],
  "tools": null
}

{
  "document": {
    "id": "draft-load-aware",
    "version": 1,
    "mode": "shadow",
    "routes": [
      "local-general",
      "local-code",
      "local-reasoning",
      "local-private"
    ],
    "default_route": "local-general",
    "evaluators": [
      {
        "id": "privacy",
        "type": "regex_text",
        "role": "force",
        "config": {
          "patterns_ref": "patterns/privacy.yaml"
        },
        "vote": {
          "route": "local-private"
        }
      },
      {
        "id": "code-text",
        "type": "regex_text",
        "config": {
          "patterns_ref": "patterns/code.yaml"
        },
        "vote": {
          "route": "local-code",
          "weight": 1.0
        }
      },
      {
        "id": "solo-busy",
        "type": "backend_load",
        "config": {
          "backends": [
            "qwen3\\.8-solo"
          ],
          "verdicts": [
            "busy",
            "down"
          ]
        },
        "vote": {
          "route": "local-reasoning",
          "weight": 0.8
        }
      }
    ],
    "combiner": {
      "type": "weighted",
      "threshold": 0.7
    }
  },
  "messages": [
    {
      "role": "user",
      "content": "What's a good name for a cat?"
    }
  ],
  "backends": {
    "http://qwen3.8-solo:8000/v1": {
      "verdict": "busy",
      "waiting": 2.0,
      "running": 3.0
    }
  }
}
